<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Cat FAQ</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --bg-accent: #131a31;
        --panel: rgba(15, 23, 42, 0.9);
        --panel-strong: rgba(30, 41, 59, 0.95);
        --border: rgba(148, 163, 184, 0.22);
        --text: #e5eefc;
        --muted: #9fb0cb;
        --primary: #7c9cff;
        --primary-strong: #9e7bff;
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.35);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 30%),
          radial-gradient(circle at 85% 10%, rgba(158, 123, 255, 0.16), transparent 25%),
          linear-gradient(180deg, #09101d 0%, #0b1020 100%);
        color: var(--text);
      }

      .page-shell {
        width: min(920px, calc(100% - 32px));
        margin: 0 auto;
        padding: 64px 0;
      }

      .hero {
        padding: 32px;
        border: 1px solid var(--border);
        border-radius: 28px;
        background: linear-gradient(180deg, rgba(15, 23, 42, 0.92), rgba(15, 23, 42, 0.76));
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-radius: 999px;
        background: rgba(124, 156, 255, 0.12);
        color: #c7d6ff;
        font-size: 0.85rem;
        letter-spacing: 0.04em;
        text-transform: uppercase;
      }

      h1 {
        margin: 18px 0 12px;
        font-size: clamp(2.2rem, 5vw, 4rem);
        line-height: 1.05;
      }

      .subtitle {
        margin: 0;
        max-width: 640px;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.7;
      }

      .faq-list {
        margin-top: 28px;
        display: grid;
        gap: 16px;
      }

      .example {
        border: 1px solid var(--border);
        border-radius: 22px;
        overflow: hidden;
        background: linear-gradient(180deg, rgba(17, 24, 39, 0.95), rgba(15, 23, 42, 0.88));
        box-shadow: 0 16px 48px rgba(0, 0, 0, 0.22);
      }

      .question-button {
        width: 100%;
        padding: 22px 24px;
        border: 0;
        background: transparent;
        color: var(--text);
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 20px;
        text-align: left;
        cursor: pointer;
        font: inherit;
      }

      .question-button:hover {
        background: rgba(124, 156, 255, 0.06);
      }

      .question-text {
        font-size: 1.05rem;
        font-weight: 700;
      }

      .indicator {
        width: 36px;
        height: 36px;
        border-radius: 50%;
        display: inline-grid;
        place-items: center;
        flex-shrink: 0;
        color: #d7e1ff;
        background: rgba(124, 156, 255, 0.12);
        transition: transform 180ms ease, background-color 180ms ease;
      }

      .question-button[aria-expanded="true"] .indicator {
        transform: rotate(45deg);
        background: rgba(158, 123, 255, 0.18);
      }

      .details {
        padding: 0 24px 24px;
        color: var(--muted);
        line-height: 1.7;
      }

      .details[hidden] {
        display: none;
      }

      .details p {
        margin: 0;
      }

      .footer-note {
        margin-top: 18px;
        color: #8192af;
        font-size: 0.95rem;
      }

      @media (max-width: 640px) {
        .page-shell {
          width: min(100% - 20px, 920px);
          padding: 20px 0 40px;
        }

        .hero {
          padding: 24px 18px;
          border-radius: 22px;
        }

        .question-button,
        .details {
          padding-left: 18px;
          padding-right: 18px;
        }
      }
    </style>
  </head>
  <body>
    <div id="app"></div>
    <script>
      const faqs = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats often purr when they feel relaxed and content, but purring can also happen when they want comfort or attention. It is a versatile sound that can signal calm, trust, or even self-soothing."
        },
        {
          question: "How much do cats sleep?",
          answer:
            "Most cats sleep between 12 and 16 hours a day, with kittens and older cats often resting even more. Their sleep pattern helps them conserve energy, reflecting their instincts as natural hunters."
        },
        {
          question: "Why do cats knead with their paws?",
          answer:
            "Kneading starts in kittenhood when they press against their mother to encourage milk flow. Adult cats often keep the habit because it feels comforting and helps them mark spaces with scent glands in their paws."
        },
        {
          question: "Do indoor cats need playtime?",
          answer:
            "Yes. Regular play gives indoor cats exercise, mental stimulation, and a healthy outlet for hunting behaviors. Short daily sessions with teaser toys, balls, or puzzle feeders can help prevent boredom."
        },
        {
          question: "Why do cats stare at people?",
          answer:
            "Cats stare to observe, communicate, and stay aware of what is happening around them. A soft gaze can be a sign of affection, while an intense stare may simply mean they are curious about your next move."
        }
      ];

      function createElement(tag, className, content) {
        const element = document.createElement(tag);
        if (className) {
          element.className = className;
        }
        if (typeof content === "string") {
          element.textContent = content;
        } else if (Array.isArray(content)) {
          content.forEach((child) => child && element.appendChild(child));
        } else if (content instanceof Node) {
          element.appendChild(content);
        }
        return element;
      }

      function FAQItem(item, index) {
        const wrapper = createElement("div", "example");
        const button = createElement("button", "question-button");
        const details = createElement("div", "details");
        const question = createElement("span", "question-text", item.question);
        const indicator = createElement("span", "indicator", "+");
        const answer = createElement("p", "", item.answer);
        const detailsId = `faq-details-${index}`;

        button.type = "button";
        button.setAttribute("aria-expanded", "false");
        button.setAttribute("aria-controls", detailsId);
        details.id = detailsId;
        details.hidden = true;

        details.appendChild(answer);
        button.append(question, indicator);
        button.addEventListener("click", () => {
          const expanded = button.getAttribute("aria-expanded") === "true";
          button.setAttribute("aria-expanded", String(!expanded));
          details.hidden = expanded;
        });

        wrapper.append(button, details);
        return wrapper;
      }

      function HeroSection() {
        const hero = createElement("section", "hero");
        const eyebrow = createElement("div", "eyebrow", "Cat care and behavior");
        const heading = createElement("h1", "", "Frequently asked questions about cats");
        const subtitle = createElement(
          "p",
          "subtitle",
          "Explore quick answers to common cat questions. Every topic starts collapsed, so you can open only the details you want."
        );
        const list = createElement("div", "faq-list", faqs.map(FAQItem));
        const footer = createElement(
          "p",
          "footer-note",
          "A calm, compact FAQ designed with a polished dark interface and accessible disclosure controls."
        );

        hero.append(eyebrow, heading, subtitle, list, footer);
        return hero;
      }

      function FAQPage() {
        const page = createElement("main", "page-shell");
        page.appendChild(HeroSection());
        return page;
      }

      function renderApp(root) {
        root.replaceChildren(FAQPage());
      }

      renderApp(document.getElementById("app"));
    </script>
  </body>
</html>
