     <script>
       const faqs = [
         {
           question: "Why do cats purr?",
           answer:
             "Cats often purr when they feel relaxed and content, but purring can also happen when they want comfort or attention. It is a versatile sound that can signal calm, trust, or even self-soothing."
         },
         {
           question: "How much do cats sleep?",
           answer:
             "Most cats sleep between 12 and 16 hours a day, with kittens and older cats often resting even more. Their sleep pattern helps them conserve energy, reflecting their instincts as natural hunters."
         },
         {
           question: "Why do cats knead with their paws?",
           answer:
             "Kneading starts in kittenhood when they press against their mother to encourage milk flow. Adult cats often keep the habit because it feels comforting and helps them mark spaces with scent glands in their paws."
         },
         {
           question: "Do indoor cats need playtime?",
           answer:
             "Yes. Regular play gives indoor cats exercise, mental stimulation, and a healthy outlet for hunting behaviors. Short daily sessions with teaser toys, balls, or puzzle feeders can help prevent boredom."
         },
         {
           question: "Why do cats stare at people?",
           answer:
             "Cats stare to observe, communicate, and stay aware of what is happening around them. A soft gaze can be a sign of affection, while an intense stare may simply mean they are curious about your next move."
         }
       ];

       function createElement(tag, className, content) {
         const element = document.createElement(tag);
         if (className) {
           element.className = className;
         }
         if (typeof content === "string") {
           element.textContent = content;
         } else if (Array.isArray(content)) {
           content.forEach((child) => child && element.appendChild(child));
         } else if (content instanceof Node) {
           element.appendChild(content);
         }
         return element;
       }

       function FAQItem(item, index) {
         const wrapper = createElement("div", "example");
         const button = createElement("button", "question-button");
         const details = createElement("div", "details");
         const question = createElement("span", "question-text", item.question);
         const indicator = createElement("span", "indicator", "+");
         const answer = createElement("p", "", item.answer);
         const detailsId = `faq-details-${index}`;

         button.type = "button";
         button.setAttribute("aria-expanded", "false");
         button.setAttribute("aria-controls", detailsId);
         details.id = detailsId;
         details.hidden = true;

         details.appendChild(answer);
         button.append(question, indicator);
         button.addEventListener("click", () => {
           const expanded = button.getAttribute("aria-expanded") === "true";
           button.setAttribute("aria-expanded", String(!expanded));
           details.hidden = expanded;
         });

         wrapper.append(button, details);
         return wrapper;
       }

       function HeroSection() {
         const hero = createElement("section", "hero");
         const eyebrow = createElement("div", "eyebrow", "Cat care and behavior");
         const heading = createElement("h1", "", "Frequently asked questions about cats");
         const subtitle = createElement(
           "p",
           "subtitle",
           "Explore quick answers to common cat questions. Every topic starts collapsed, so you can open only the details you want."
         );
         const list = createElement("div", "faq-list", faqs.map(FAQItem));
         const footer = createElement(
           "p",
           "footer-note",
           "A calm, compact FAQ designed with a polished dark interface and accessible disclosure controls."
         );
